                <span className="font-bold text-slate-800">Stock Availability:</span>
              </div>
              <span
                className={`font-bold px-2 py-0.5 rounded-full text-xs ${
                  selectedPart.stock_quantity === 0 || selectedPart.availability === "OUT_OF_STOCK"
