"use client";

import React, { useEffect, useRef, useState } from "react";
import {
  ShoppingCart,
  X,
  Plus,
  Minus,
  Trash2,
  Store,
  AlertCircle,
  AlertTriangle,
  CheckCircle2,
  ArrowRight,
  ArrowLeft,
  ShieldCheck,
  RefreshCw,
  Wrench,
  PackageCheck,
  Car,
  MapPin,
  Phone,
  User as UserIcon,
  Check,
  Copy,
  Loader2,
  Receipt,
  Truck,
  Building,
  Package,
  CreditCard,
  Banknote,
  Clock,
} from "lucide-react";
import { useCart, CartItem } from "@/context/CartContext";
import {
  api,
  ApiError,
  resolveMediaUrl,
  PlatformOrder,
  PaymentMethodOption,
  PaymentVerifyPayload,
} from "@/lib/api/client";
import { useAuth } from "@/lib/prototype-auth/auth-context";

interface CartDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  onNavigate?: (tab: string, itemData?: { type: string; id: string; raw?: unknown }) => void;
}

type CheckoutStep = "cart" | "shipping" | "review" | "confirmed";

interface ShippingFormData {
  shipping_name: string;
  shipping_phone: string;
  shipping_address_line1: string;
  shipping_address_line2: string;
  shipping_city: string;
  shipping_state: string;
  shipping_postal_code: string;
  shipping_country: string;
}

interface CalculatedItem {
  listing_id: string;
  title: string;
  brand: string;
  mpn?: string;
  hsn_code?: string;
  gst_rate: string;
  unit_price: string;
  quantity: number;
  taxable_amount: string;
  cgst_amount: string;
  sgst_amount: string;
  igst_amount: string;
  tax_amount: string;
  total_amount: string;
}

interface AuthoritativeCalculation {
  subtotal_taxable_amount: string;
  cgst_amount: string;
  sgst_amount: string;
  igst_amount: string;
  total_tax_amount: string;
  total_amount: string;
  currency: string;
  place_of_supply?: string;
  seller_state?: string;
  items: CalculatedItem[];
}

const INDIAN_STATES = [
  { code: "MH", name: "Maharashtra (MH)" },
  { code: "DL", name: "Delhi (DL)" },
  { code: "KA", name: "Karnataka (KA)" },
  { code: "TN", name: "Tamil Nadu (TN)" },
  { code: "TS", name: "Telangana (TS)" },
  { code: "GJ", name: "Gujarat (GJ)" },
  { code: "UP", name: "Uttar Pradesh (UP)" },
  { code: "HR", name: "Haryana (HR)" },
  { code: "WB", name: "West Bengal (WB)" },
  { code: "RJ", name: "Rajasthan (RJ)" },
  { code: "KL", name: "Kerala (KL)" },
  { code: "AP", name: "Andhra Pradesh (AP)" },
  { code: "MP", name: "Madhya Pradesh (MP)" },
  { code: "PB", name: "Punjab (PB)" },
  { code: "BR", name: "Bihar (BR)" },
  { code: "OR", name: "Odisha (OR)" },
  { code: "AS", name: "Assam (AS)" },
  { code: "CH", name: "Chandigarh (CH)" },
  { code: "GA", name: "Goa (GA)" },
  { code: "UK", name: "Uttarakhand (UK)" },
  { code: "JH", name: "Jharkhand (JH)" },
];

const UK_REGIONS = [
  { code: "London", name: "Greater London" },
  { code: "South East", name: "South East England" },
  { code: "North West", name: "North West England" },
  { code: "West Midlands", name: "West Midlands" },
  { code: "Yorkshire", name: "Yorkshire and the Humber" },
  { code: "Scotland", name: "Scotland" },
  { code: "Wales", name: "Wales" },
  { code: "Northern Ireland", name: "Northern Ireland" },
  { code: "East Midlands", name: "East Midlands" },
  { code: "South West", name: "South West England" },
];

function loadRazorpayScript(): Promise<boolean> {
  return new Promise((resolve) => {
    if (typeof window === "undefined") {
      resolve(false);
      return;
    }
    if ((window as any).Razorpay) {
      resolve(true);
      return;
    }
    const existing = document.getElementById("razorpay-checkout-js");
    if (existing) {
      if ((window as any).Razorpay) {
        resolve(true);
      } else {
        existing.addEventListener("load", () => resolve(true));
        existing.addEventListener("error", () => resolve(false));
      }
      return;
    }
    const script = document.createElement("script");
    script.id = "razorpay-checkout-js";
    script.src = "https://checkout.razorpay.com/v1/checkout.js";
    script.async = true;
    script.onload = () => resolve(true);
    script.onerror = () => resolve(false);
    document.body.appendChild(script);
  });
}

function loadStripeScript(): Promise<boolean> {
  return new Promise((resolve) => {
    if (typeof window === "undefined") {
      resolve(false);
      return;
    }
    if ((window as any).Stripe) {
      resolve(true);
      return;
    }
    const existing = document.getElementById("stripe-js");
    if (existing) {
      if ((window as any).Stripe) {
        resolve(true);
      } else {
        existing.addEventListener("load", () => resolve(true));
        existing.addEventListener("error", () => resolve(false));
      }
      return;
    }
    const script = document.createElement("script");
    script.id = "stripe-js";
    script.src = "https://js.stripe.com/v3/";
    script.async = true;
    script.onload = () => resolve(true);
    script.onerror = () => resolve(false);
    document.body.appendChild(script);
  });
}

export default function CartDrawer({ isOpen, onClose, onNavigate }: CartDrawerProps) {
  const { user } = useAuth();
  const {
    items,
    totalUnits,
    distinctItemCount,
    displayedSubtotal,
    currency,
    groupedBySeller,
    updateQuantity,
    removeItem,
    clearCart,
    validateInventory,
    isValidating,
    lastValidationResult,
  } = useCart();

  // Multi-step checkout states
  const [step, setStep] = useState<CheckoutStep>("cart");
  const [confirmClearOpen, setConfirmClearOpen] = useState(false);
  const [checkoutNotice, setCheckoutNotice] = useState<string | null>(null);
  const [checkoutError, setCheckoutError] = useState<string | null>(null);
  const [priceChangeAlert, setPriceChangeAlert] = useState<{
    reviewed: string;
    updated: string;
  } | null>(null);

  // Loading & submission locks
  const [isCalculating, setIsCalculating] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [idempotencyKey, setIdempotencyKey] = useState<string>("");
  const [copiedOrderId, setCopiedOrderId] = useState(false);

  // Authoritative calculation & order confirmation data
  const [calculation, setCalculation] = useState<AuthoritativeCalculation | null>(null);
  const [confirmedOrder, setConfirmedOrder] = useState<PlatformOrder | null>(null);
  const [pendingSession, setPendingSession] = useState<any>(null);
  const [isCancellingOrder, setIsCancellingOrder] = useState<boolean>(false);

  // Shipping Form State
  const [shippingForm, setShippingForm] = useState<ShippingFormData>({
    shipping_name: "",
    shipping_phone: "",
    shipping_address_line1: "",
    shipping_address_line2: "",
    shipping_city: "",
    shipping_state: "MH",
    shipping_postal_code: "",
    shipping_country: "India",
  });
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});

  // Payment Method & Status
  const [paymentMethod, setPaymentMethod] = useState<"ONLINE" | "COD">("ONLINE");
  const [availableMethods, setAvailableMethods] = useState<PaymentMethodOption[]>([]);
  const [isVerifyingPayment, setIsVerifyingPayment] = useState(false);
  const [paymentVerifiedSuccess, setPaymentVerifiedSuccess] = useState<string | null>(null);

  const getCurrencyForCountry = (country: string): "GBP" | "INR" => {
    const norm = (country || "").trim().toLowerCase();
    if (norm.includes("kingdom") || norm === "gb" || norm === "uk") {
      return "GBP";
    }
    return "INR";
  };

  const getValidRegionForCountry = (country: string, currentRegion?: string): string => {
    const isUK = getCurrencyForCountry(country) === "GBP";
    if (isUK) {
      const exists = UK_REGIONS.some((r) => r.code === currentRegion);
      return exists ? (currentRegion as string) : "London";
    } else {
      const exists = INDIAN_STATES.some((s) => s.code === currentRegion);
      return exists ? (currentRegion as string) : "MH";
    }
  };

  const handleCountryChange = (newCountry: string) => {
    const validRegion = getValidRegionForCountry(newCountry, shippingForm.shipping_state);
    const newCurrency = getCurrencyForCountry(newCountry);
    setShippingForm((prev) => ({
      ...prev,
      shipping_country: newCountry,
      shipping_state: validRegion,
      shipping_postal_code: "",
    }));
    setFieldErrors({});
    setCalculation(null);
    setAvailableMethods([]);
    setCheckoutError(null);
    setPriceChangeAlert(null);
    if (step === "review") {
      setStep("shipping");
    }
    // Refresh authoritative prices and stock for the new destination country
    validateInventory({
      country: newCountry,
      currency: newCurrency,
      place_of_supply: validRegion,
    });
  };


  const openRazorpayCheckout = async (order: PlatformOrder, session: any) => {
    setIsVerifyingPayment(true);
    setCheckoutError(null);

    let activeSession = session;
    if (activeSession && activeSession.is_available === false) {
      setIsVerifyingPayment(false);
      setIsSubmitting(false);
      setConfirmedOrder(order);
      setStep("confirmed");
      setCheckoutError(activeSession.error || "Online payments are currently unavailable on this server.");
      return;
    }
    if (!activeSession || !activeSession.provider_order_id) {
      try {
        const sessionRes = await api.marketplace.createPaymentSession(order.id);
        if (sessionRes && sessionRes.payment_session) {
          activeSession = sessionRes.payment_session;
          setPendingSession(activeSession);
        }
      } catch (err: unknown) {
        console.warn("Could not retrieve fresh payment session:", err);
      }
    }

    const loaded = await loadRazorpayScript();
    if (!loaded || !(window as any).Razorpay) {
      setIsVerifyingPayment(false);
      setIsSubmitting(false);
      setConfirmedOrder(order);
      setStep("confirmed");
      setCheckoutError("Razorpay Checkout SDK could not be loaded directly. You can complete verification in test mode or retry.");
      return;
    }

    try {
      const options: any = {
        key: activeSession?.key_id || process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID || "rzp_test_placeholder_key",
        amount: activeSession?.amount_minor || Math.round(Number(order.total_amount) * 100),
        currency: activeSession?.currency || order.currency || "INR",
        name: "DriverXtra Platform",
        description: `Order ${order.order_number}`,
        order_id: activeSession?.provider_order_id || order.payment_reference,
        prefill: {
          name: shippingForm.shipping_name || user?.fullName || "",
          email: user?.email || "",
          contact: shippingForm.shipping_phone || "",
        },
        notes: {
          order_number: order.order_number,
          order_id: order.id,
        },
        theme: {
          color: "#f59e0b",
        },
        config: {
          display: {
            blocks: {
              upi: {
                name: "Pay via UPI",
                instruments: [
                  {
                    method: "upi",
                  },
                ],
              },
              other: {
                name: "Cards, NetBanking & Wallets",
                instruments: [
                  { method: "card" },
                  { method: "netbanking" },
                  { method: "wallet" },
                ],
              },
            },
            sequence: ["block.upi", "block.other"],
            preferences: {
              show_default_blocks: true,
            },
          },
        },
        handler: async function (response: {
          razorpay_payment_id: string;
          razorpay_order_id: string;
          razorpay_signature: string;
        }) {
          setIsVerifyingPayment(true);
          setCheckoutError(null);
          try {
            const verifyRes = await api.marketplace.verifyPayment(order.id, {
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_order_id: response.razorpay_order_id,
              razorpay_signature: response.razorpay_signature,
              amount: order.total_amount,
              currency: order.currency,
            });
            if (verifyRes.status === "success" && verifyRes.order) {
              clearCart(); // Cart cleared ONLY on verified success!
              setIdempotencyKey("");
              setConfirmedOrder(verifyRes.order);
              setStep("confirmed");
              setPaymentVerifiedSuccess("Online payment verified and confirmed via Razorpay!");
            } else {
              setCheckoutError(verifyRes.error || "Payment verification failed.");
            }
          } catch (err: unknown) {
            setCheckoutError(err instanceof Error ? err.message : "Payment verification failed.");
          } finally {
            setIsVerifyingPayment(false);
            setIsSubmitting(false);
          }
        },
        modal: {
          confirm_close: true,
          ondismiss: function () {
            setIsSubmitting(false);
            setIsVerifyingPayment(false);
            setConfirmedOrder(order);
            setStep("confirmed");
            setCheckoutError("Payment checkout was cancelled or dismissed. Your order is pending payment and stock is reserved. You can complete payment below or cancel the order to restore items.");
          },
        },
      };

      const rzp = new (window as any).Razorpay(options);
      rzp.on("payment.failed", async function (resp: any) {
        setIsSubmitting(false);
        setIsVerifyingPayment(false);
        const desc = resp?.error?.description || "Payment failed or was declined.";
        const payId = resp?.error?.metadata?.payment_id || resp?.error?.payment_id || "";
        const code = resp?.error?.code || "";
        try {
          await api.marketplace.reportPaymentFailure(order.id, {
            reason: desc,
            error_description: desc,
            payment_id: payId,
            error_code: code,
          });
        } catch (failErr) {
          console.warn("Could not report payment failure to server:", failErr);
        }
        setConfirmedOrder(order);
        setStep("confirmed");
        setCheckoutError(`Payment failed: ${desc}. Please retry or choose another payment method.`);
      });
      rzp.open();
    } catch (e: any) {
      setIsSubmitting(false);
      setIsVerifyingPayment(false);
      setConfirmedOrder(order);
      setStep("confirmed");
      setCheckoutError(e?.message || "Failed to launch Razorpay Checkout. Please check your network connection and retry.");
    }
  };

  const openStripeCheckout = async (order: PlatformOrder, session: any) => {
    setIsVerifyingPayment(true);
    setCheckoutError(null);

    let activeSession = session;
    if (activeSession && activeSession.is_available === false) {
      setIsVerifyingPayment(false);
      setIsSubmitting(false);
      setConfirmedOrder(order);
      setStep("confirmed");
      setCheckoutError(activeSession.error || "Online card payments via Stripe are currently unavailable on this server.");
      return;
    }

    if (!activeSession || !activeSession.provider_order_id) {
      try {
        const sessionRes = await api.marketplace.createPaymentSession(order.id);
        if (sessionRes && sessionRes.payment_session) {
          activeSession = sessionRes.payment_session;
          setPendingSession(activeSession);
        }
      } catch (err: unknown) {
        console.warn("Could not retrieve fresh Stripe payment session:", err);
      }
    }

    // In automated testing or test mode environment: verify with server sandbox
    if (activeSession?.is_test_mode) {
      try {
        const verifyRes = await api.marketplace.verifyPayment(order.id, {
          payment_intent_id: activeSession.provider_order_id,
          client_secret: activeSession.client_secret,
          amount: order.total_amount,
          currency: order.currency,
        });
        if (verifyRes.status === "success" && verifyRes.order) {
          clearCart(); // Cart cleared ONLY on verified success!
          setIdempotencyKey("");
          setConfirmedOrder(verifyRes.order);
          setStep("confirmed");
          setPaymentVerifiedSuccess("Online payment verified and confirmed via Stripe Sandbox!");
        } else {
          setConfirmedOrder(order);
          setStep("confirmed");
          setCheckoutError(verifyRes.error || "Stripe payment verification failed.");
        }
      } catch (err: unknown) {
        setConfirmedOrder(order);
        setStep("confirmed");
        setCheckoutError(err instanceof Error ? err.message : "Stripe payment verification failed.");
      } finally {
        setIsVerifyingPayment(false);
        setIsSubmitting(false);
      }
      return;
    }

    // For live Stripe web checkout:
    const loaded = await loadStripeScript();
    if (!loaded || !(window as any).Stripe) {
      setIsVerifyingPayment(false);
      setIsSubmitting(false);
      setConfirmedOrder(order);
      setStep("confirmed");
      setCheckoutError("Stripe Checkout SDK could not be loaded directly. You can complete verification in test mode or retry.");
      return;
    }

    try {
      const pubKey = activeSession?.publishable_key || process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY || "pk_test_placeholder_key";
      const stripe = (window as any).Stripe(pubKey);
      if (!stripe) {
        throw new Error("Unable to initialize Stripe payment service.");
      }

      const verifyRes = await api.marketplace.verifyPayment(order.id, {
        payment_intent_id: activeSession.provider_order_id,
        client_secret: activeSession.client_secret,
        amount: order.total_amount,
        currency: order.currency,
      });

      if (verifyRes.status === "success" && verifyRes.order) {
        clearCart();
        setIdempotencyKey("");
        setConfirmedOrder(verifyRes.order);
        setStep("confirmed");
        setPaymentVerifiedSuccess("Online payment verified and confirmed via Stripe!");
      } else {
        setConfirmedOrder(order);
        setStep("confirmed");
        setCheckoutError(verifyRes.error || "Stripe payment verification failed.");
      }
    } catch (e: any) {
      setIsSubmitting(false);
      setIsVerifyingPayment(false);
      const desc = e?.message || "Payment failed or was declined.";
      try {
        await api.marketplace.reportPaymentFailure(order.id, {
          reason: desc,
          error_description: desc,
          payment_id: activeSession?.provider_order_id || "",
        });
      } catch (failErr) {
        console.warn("Could not report payment failure to server:", failErr);
      }
      setConfirmedOrder(order);
      setStep("confirmed");
      setCheckoutError(`Payment failed: ${desc}. Please retry or choose another payment method.`);
    } finally {
      setIsVerifyingPayment(false);
      setIsSubmitting(false);
    }
  };

  const handleCancelUnpaidOrder = async () => {
    if (!confirmedOrder || isCancellingOrder) return;
    setIsCancellingOrder(true);
    setCheckoutError(null);
    try {
      const res = await api.marketplace.cancelPayment(confirmedOrder.id, "Payment cancelled by buyer.");
      if (res.status === "success") {
        setConfirmedOrder(null);
        setPendingSession(null);
        setIdempotencyKey("");
        setStep("cart");
        setPaymentVerifiedSuccess(null);
      } else {
        setCheckoutError(res.error || "Failed to cancel order.");
      }
    } catch (err: unknown) {
      setCheckoutError(err instanceof Error ? err.message : "Failed to cancel order.");
    } finally {
      setIsCancellingOrder(false);
    }
  };

  const handleSimulatePayment = async () => {
    if (!confirmedOrder || isVerifyingPayment) return;
    setIsVerifyingPayment(true);
    setCheckoutError(null);
    try {
      const res = await api.marketplace.simulateTestPayment(confirmedOrder.id);
      if (res.status === "success" && res.order) {
        setConfirmedOrder(res.order);
        setPaymentVerifiedSuccess("Online payment verified and confirmed via provider sandbox!");
      } else {
        setCheckoutError(res.error || "Payment verification failed.");
      }
    } catch (err: unknown) {
      setCheckoutError(err instanceof Error ? err.message : "Payment verification failed.");
    } finally {
      setIsVerifyingPayment(false);
    }
  };

  const drawerRef = useRef<HTMLDivElement>(null);

  // Auto-fill user details when available
  useEffect(() => {
    if (user) {
      setShippingForm((prev) => ({
        ...prev,
        shipping_name: prev.shipping_name || user.fullName || "",
      }));
    }
  }, [user]);

  // Reset checkout flow when drawer is opened/closed
  useEffect(() => {
    if (!isOpen) {
      // If order was confirmed, reset to cart step for next open
      if (step === "confirmed") {
        setStep("cart");
        setConfirmedOrder(null);
      }
      setCheckoutNotice(null);
      setCheckoutError(null);
      setPriceChangeAlert(null);
    }
  }, [isOpen, step]);

  // Close on Escape key
  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        onClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  // Lock body scroll when open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen]);

  if (!isOpen) return null;

  // Helpers
  const partItems = items.filter((i) => i.listing_type !== "vehicle");
  const hasVehicles = items.some((i) => i.listing_type === "vehicle");

  const generateNewIdempotencyKey = () => {
    if (typeof crypto !== "undefined" && crypto.randomUUID) {
      return crypto.randomUUID();
    }
    return `dx-idem-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
  };

  const handleBrowseParts = () => {
    onClose();
    if (onNavigate) {
      onNavigate("marketplace_browse");
    }
  };

  // Step 1 -> Step 2: Proceed from Cart to Shipping
  const handleProceedToShipping = async () => {
    setCheckoutNotice(null);
    setCheckoutError(null);
    setPriceChangeAlert(null);

    if (hasVehicles) {
      setCheckoutError(
        "Notice: Your cart contains a vehicle listing. Motor vehicles require legal documentation, physical inspection, and direct seller consultation. Please use the Contact Seller enquiry flow; online automated checkout is reserved exclusively for spare parts."
      );
      return;
    }

    if (partItems.length === 0) {
      setCheckoutError("Your cart contains no spare parts to checkout.");
      return;
    }

    if (!user) {
      setCheckoutError(
        "Please sign in to your DriverXtra account to place an order with verified statutory taxes and delivery details."
      );
      return;
    }

    // Verify stock and fetch authoritative totals for selected destination
    const destCurrency = getCurrencyForCountry(shippingForm.shipping_country);
    const valResult = await validateInventory({
      country: shippingForm.shipping_country,
      currency: destCurrency,
      place_of_supply: shippingForm.shipping_state,
    });
    if (!valResult.isValid) {
      return;
    }

    setStep("shipping");
  };

  // Step 2 -> Step 3: Validate Shipping Form & Calculate Authoritative Tax
  const handleProceedToReview = async () => {
    setCheckoutError(null);
    setPriceChangeAlert(null);

    // Validate fields
    const errors: Record<string, string> = {};
    if (!shippingForm.shipping_name.trim()) {
      errors.shipping_name = "Full name is required for delivery.";
    }
    const cleanPhone = shippingForm.shipping_phone.replace(/[^0-9+]/g, "");
    if (!shippingForm.shipping_phone.trim()) {
      errors.shipping_phone = "Contact phone number is required.";
    } else if (cleanPhone.length < 7) {
      errors.shipping_phone = "A valid phone number (at least 7 digits) is required.";
    }
    if (!shippingForm.shipping_address_line1.trim()) {
      errors.shipping_address_line1 = "Delivery street address is required.";
    }
    if (!shippingForm.shipping_city.trim()) {
      errors.shipping_city = "City is required.";
    }
    if (!shippingForm.shipping_state.trim()) {
      errors.shipping_state = "State / Place of supply is required.";
    }
    if (!shippingForm.shipping_postal_code.trim()) {
      errors.shipping_postal_code = "Postal / PIN code is required.";
    }

    setFieldErrors(errors);
    if (Object.keys(errors).length > 0) {
      setCheckoutError("Please fill in all required shipping and contact details.");
      return;
    }

    const destCurrency = getCurrencyForCountry(shippingForm.shipping_country);

    setIsCalculating(true);
    try {
      const payload = {
        items: partItems.map((i) => ({
          listing_id: i.listing_id,
          quantity: i.quantity,
        })),
        place_of_supply: shippingForm.shipping_state,
        shipping_name: shippingForm.shipping_name.trim(),
        shipping_phone: shippingForm.shipping_phone.trim(),
        shipping_address_line1: shippingForm.shipping_address_line1.trim(),
        shipping_address_line2: shippingForm.shipping_address_line2.trim(),
        shipping_city: shippingForm.shipping_city.trim(),
        shipping_state: shippingForm.shipping_state.trim(),
        shipping_postal_code: shippingForm.shipping_postal_code.trim(),
        shipping_country: shippingForm.shipping_country.trim() || "India",
        currency: destCurrency,
      };

      const res = await api.marketplace.calculateCheckout(payload);

      const itemsList: CalculatedItem[] = Array.isArray(res.items)
        ? (res.items as CalculatedItem[])
        : [];

      const calcData: AuthoritativeCalculation = {
        subtotal_taxable_amount: String(res.subtotal_taxable_amount || "0.00"),
        cgst_amount: String(res.cgst_amount || "0.00"),
        sgst_amount: String(res.sgst_amount || "0.00"),
        igst_amount: String(res.igst_amount || "0.00"),
        total_tax_amount: String(res.total_tax_amount || "0.00"),
        total_amount: String(res.total_amount || "0.00"),
        currency: String(res.currency || destCurrency),
        place_of_supply: String(res.place_of_supply || shippingForm.shipping_state),
        seller_state: String(res.seller_state || ""),
        items: itemsList,
      };

      setCalculation(calcData);
      if (Array.isArray(res.available_payment_methods)) {
        const methods = res.available_payment_methods as PaymentMethodOption[];
        setAvailableMethods(methods);
        const cod = methods.find((m) => m.code === "COD");
        const online = methods.find((m) => m.code === "ONLINE");
        if (cod && !cod.is_available && paymentMethod === "COD") {
          setPaymentMethod("ONLINE");
        } else if (online && !online.is_available && paymentMethod === "ONLINE" && cod && cod.is_available) {
          setPaymentMethod("COD");
        }
      }

      // Ensure idempotency key is initialized for this checkout attempt
      if (!idempotencyKey) {
        setIdempotencyKey(generateNewIdempotencyKey());
      }
      setStep("review");
    } catch (err: unknown) {
      let msg = "Failed to calculate order taxes. Please check your delivery address and try again.";
      if (err instanceof ApiError) {
        msg = err.message;
      } else if (err instanceof Error) {
        msg = err.message;
      }
      setCheckoutError(msg);
    } finally {
      setIsCalculating(false);
    }
  };

  // Step 3 -> Step 4: Final Submit Order
  const handleSubmitOrder = async () => {
    if (!calculation || isSubmitting) return;

    const destCurrency = getCurrencyForCountry(shippingForm.shipping_country);
    if (calculation.currency !== destCurrency) {
      setCheckoutError(
        `Calculation currency (${calculation.currency}) does not match destination country currency (${destCurrency}). Please review taxes again.`
      );
      return;
    }

    setIsSubmitting(true);
    setCheckoutError(null);

    const activeIdempotencyKey = idempotencyKey || generateNewIdempotencyKey();
    if (!idempotencyKey) {
      setIdempotencyKey(activeIdempotencyKey);
    }

    try {
      const payload = {
        items: partItems.map((i) => ({
          listing_id: i.listing_id,
          quantity: i.quantity,
        })),
        place_of_supply: shippingForm.shipping_state,
        shipping_name: shippingForm.shipping_name.trim(),
        shipping_phone: shippingForm.shipping_phone.trim(),
        shipping_address_line1: shippingForm.shipping_address_line1.trim(),
        shipping_address_line2: shippingForm.shipping_address_line2.trim(),
        shipping_city: shippingForm.shipping_city.trim(),
        shipping_state: shippingForm.shipping_state.trim(),
        shipping_postal_code: shippingForm.shipping_postal_code.trim(),
        shipping_country: shippingForm.shipping_country.trim() || "India",
        currency: destCurrency,
        payment_method: paymentMethod,
        expected_total_amount: calculation.total_amount,
        idempotency_key: activeIdempotencyKey,
      };

      const res = await api.marketplace.checkout(payload);

      if (res.status === "success" && res.order) {
        setPendingSession(res.payment_session);
        if (paymentMethod === "COD") {
          // COD order is immediately confirmed without online payment
          clearCart();
          setConfirmedOrder(res.order);
          setStep("confirmed");
        } else {
          // ONLINE payment: keep cart until verified! Launch provider checkout
          setConfirmedOrder(res.order);
          const isStripe = res.payment_session?.provider === "STRIPE" || destCurrency === "GBP" || res.order.currency === "GBP";
          if (isStripe) {
            await openStripeCheckout(res.order, res.payment_session);
          } else {
            await openRazorpayCheckout(res.order, res.payment_session);
          }
        }
      } else {
        throw new Error(res.message || "Failed to create order.");
      }
    } catch (err: unknown) {
      // PRICE CHANGED (HTTP 409)
      if (err instanceof ApiError && err.code === 409) {
        const details = err.details as Record<string, unknown> | undefined;
        const reviewedTotal = String(details?.reviewed_total_amount || calculation.total_amount);
        const updatedTotal = String(details?.updated_total_amount || "");

        if (updatedTotal) {
          setPriceChangeAlert({
            reviewed: reviewedTotal,
            updated: updatedTotal,
          });
          // Update calculation with newly authoritative values
          setCalculation((prev) =>
            prev
              ? {
                  ...prev,
                  total_amount: updatedTotal,
                  subtotal_taxable_amount: String(details?.subtotal_taxable_amount || prev.subtotal_taxable_amount),
                  total_tax_amount: String(details?.total_tax_amount || prev.total_tax_amount),
                }
              : null
          );
        } else {
          setPriceChangeAlert({
            reviewed: reviewedTotal,
            updated: "Updated Total",
          });
        }
        setCheckoutError(err.message);
        // Cart is NOT cleared!
        return;
      }

      // Other ApiError or Network failure
      let msg = "An error occurred during checkout submission.";
      if (err instanceof ApiError) {
        msg = err.message;
      } else if (err instanceof Error) {
        msg = err.message;
      }
      setCheckoutError(msg);
      // Cart is NOT cleared on failure or timeout!
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleCopyOrderId = (idToCopy: string) => {
    if (navigator?.clipboard?.writeText) {
      navigator.clipboard.writeText(idToCopy);
      setCopiedOrderId(true);
      setTimeout(() => setCopiedOrderId(false), 2000);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex justify-end animate-in fade-in duration-200"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-label="Shopping Cart & Checkout"
    >
      <div
        ref={drawerRef}
        className="bg-white w-full max-w-xl h-full shadow-2xl flex flex-col border-l border-slate-200 animate-in slide-in-from-right duration-250 select-none"
        onClick={(e) => e.stopPropagation()}
      >
        {/* ========================================================= */}
        {/* TOP BAR / STEP HEADER                                      */}
        {/* ========================================================= */}
        <div className="p-4 sm:p-5 border-b border-slate-200 flex items-center justify-between bg-slate-900 text-white shrink-0">
          <div className="flex items-center gap-3">
            {step === "cart" ? (
              <div className="w-9 h-9 rounded-xl bg-amber-400 text-slate-950 flex items-center justify-center font-black shadow-md">
                <ShoppingCart className="w-5 h-5" />
              </div>
            ) : step === "shipping" ? (
              <button
                type="button"
                onClick={() => setStep("cart")}
                className="w-9 h-9 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 flex items-center justify-center transition-colors"
                title="Back to Cart"
              >
                <ArrowLeft className="w-5 h-5" />
              </button>
            ) : step === "review" ? (
              <button
                type="button"
                onClick={() => setStep("shipping")}
                className="w-9 h-9 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 flex items-center justify-center transition-colors"
                title="Back to Shipping Details"
              >
                <ArrowLeft className="w-5 h-5" />
              </button>
            ) : (
              <div className="w-9 h-9 rounded-xl bg-emerald-500 text-white flex items-center justify-center font-black shadow-md">
                <CheckCircle2 className="w-5 h-5" />
              </div>
            )}

            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base font-black tracking-tight">
                  {step === "cart" && "Shopping Cart"}
                  {step === "shipping" && "Checkout: Delivery Address"}
                  {step === "review" && "Checkout: Review & Confirm"}
                  {step === "confirmed" && "Order Placed Successfully"}
                </h3>
                {step === "cart" && totalUnits > 0 && (
                  <span className="px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-400 border border-amber-400/30 text-[10px] font-black font-mono">
                    {totalUnits} {totalUnits === 1 ? "unit" : "units"}
                  </span>
                )}
              </div>
              <p className="text-[11px] text-slate-400">
                {step === "cart" && "Marketplace Checkout · Spare Parts"}
                {step === "shipping" && "Step 1 of 2: Shipping & Contact Information"}
                {step === "review" && "Step 2 of 2: Authoritative Tax Breakdown & Confirmation"}
                {step === "confirmed" && "Order placed successfully"}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {step === "cart" && items.length > 0 && (
              <button
                type="button"
                onClick={() => setConfirmClearOpen(true)}
                className="text-[11px] font-bold text-slate-400 hover:text-rose-400 px-2 py-1 rounded-lg hover:bg-slate-800 transition-colors"
                title="Clear all cart items"
              >
                Clear Cart
              </button>
            )}
            <button
              onClick={onClose}
              className="p-1.5 rounded-xl text-slate-400 hover:text-white hover:bg-slate-800 transition-colors"
              aria-label="Close drawer"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Step Progress Bar (when checking out) */}
        {step !== "cart" && (
          <div className="bg-slate-800 px-5 py-2.5 flex items-center justify-between text-[11px] font-bold text-slate-400 border-b border-slate-700">
            <div className={`flex items-center gap-1.5 ${step === "shipping" ? "text-amber-400" : "text-emerald-400"}`}>
              <span className="w-5 h-5 rounded-full bg-slate-700 flex items-center justify-center text-[10px]">1</span>
              <span>Delivery Details</span>
            </div>
            <div className="w-8 h-px bg-slate-700" />
            <div className={`flex items-center gap-1.5 ${step === "review" ? "text-amber-400" : step === "confirmed" ? "text-emerald-400" : "text-slate-500"}`}>
              <span className="w-5 h-5 rounded-full bg-slate-700 flex items-center justify-center text-[10px]">2</span>
              <span>Review & Taxes</span>
            </div>
            <div className="w-8 h-px bg-slate-700" />
            <div className={`flex items-center gap-1.5 ${step === "confirmed" ? "text-emerald-400" : "text-slate-500"}`}>
              <span className="w-5 h-5 rounded-full bg-slate-700 flex items-center justify-center text-[10px]">3</span>
              <span>Confirmed</span>
            </div>
          </div>
        )}

        {/* Clear Confirmation Prompt */}
        {confirmClearOpen && (
          <div className="p-3 bg-rose-50 border-b border-rose-200 text-rose-900 text-xs flex items-center justify-between gap-3 animate-in fade-in duration-150">
            <div className="flex items-center gap-2">
              <AlertTriangle className="w-4 h-4 text-rose-600 shrink-0" />
              <span>Are you sure you want to remove all items from your cart?</span>
            </div>
            <div className="flex items-center gap-2 shrink-0">
              <button
                type="button"
                onClick={() => {
                  clearCart();
                  setConfirmClearOpen(false);
                }}
                className="px-2.5 py-1 bg-rose-600 hover:bg-rose-700 text-white rounded-lg font-bold text-[11px]"
              >
                Yes, Clear
              </button>
              <button
                type="button"
                onClick={() => setConfirmClearOpen(false)}
                className="px-2.5 py-1 bg-white hover:bg-slate-100 text-slate-700 rounded-lg font-bold text-[11px] border border-slate-200"
              >
                Cancel
              </button>
            </div>
          </div>
        )}

        {/* Error Alert Banner */}
        {checkoutError && (
          <div className="p-3 bg-rose-50 border-b border-rose-200 text-rose-950 text-xs flex items-start gap-2 animate-in fade-in duration-150">
            <AlertCircle className="w-4 h-4 text-rose-600 shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="font-semibold text-rose-900">{checkoutError}</p>
            </div>
            <button
              type="button"
              onClick={() => setCheckoutError(null)}
              className="text-rose-700 hover:text-rose-900 p-0.5"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        )}

        {/* Price Change Explicit Notice Banner */}
        {priceChangeAlert && (
          <div className="p-3 bg-amber-500/10 border-b border-amber-400 text-amber-950 text-xs flex items-start gap-2 animate-in fade-in duration-150">
            <AlertTriangle className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
            <div className="flex-1 space-y-1">
              <p className="font-black text-amber-900">
                Action Required: Order Total Updated by Seller/Tax Rules
              </p>
              <p className="text-[11px] text-amber-900">
                The authoritative server total has changed from{" "}
                <span className="font-mono font-bold line-through">{priceChangeAlert.reviewed}</span> to{" "}
                <span className="font-mono font-black text-slate-950 bg-amber-200 px-1 py-0.5 rounded">
                  {priceChangeAlert.updated}
                </span>{" "}
                due to live listing price updates or place-of-supply statutory taxes. Please review the updated total and explicitly confirm before submission.
              </p>
            </div>
            <button
              type="button"
              onClick={() => setPriceChangeAlert(null)}
              className="text-amber-800 hover:text-amber-950 p-0.5"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        )}

        {/* Notice Banner */}
        {checkoutNotice && (
          <div className="p-3 bg-emerald-50 border-b border-emerald-200 text-emerald-950 text-xs flex items-start gap-2 animate-in fade-in duration-150">
            <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0 mt-0.5" />
            <div className="flex-1">
              <p className="font-semibold">{checkoutNotice}</p>
            </div>
            <button
              type="button"
              onClick={() => setCheckoutNotice(null)}
              className="text-emerald-700 hover:text-emerald-900 p-0.5"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        )}

        {/* Destination Country Quick-Switch Banner */}
        {step !== "confirmed" && (
          <div className="bg-slate-100/90 border-b border-slate-200 px-4 py-2.5 flex items-center justify-between gap-3 text-xs">
            <div className="flex items-center gap-1.5 min-w-0">
              <MapPin className="w-3.5 h-3.5 text-amber-600 shrink-0" />
              <span className="text-slate-600 font-medium">Deliver to:</span>
              <span className="font-black text-slate-900 truncate">
                {shippingForm.shipping_country === "United Kingdom"
                  ? "United Kingdom (GBP £)"
                  : "India (INR ₹)"}
              </span>
            </div>
            <div className="flex items-center gap-1 shrink-0">
              <button
                type="button"
                id="cart-country-india-btn"
                onClick={() => handleCountryChange("India")}
                className={`px-2 py-1 text-[11px] font-bold rounded-lg border transition-all ${
                  shippingForm.shipping_country === "India"
                    ? "bg-amber-500 text-slate-950 border-amber-600 shadow-xs"
                    : "bg-white text-slate-700 border-slate-300 hover:bg-slate-50"
                }`}
              >
                🇮🇳 India
              </button>
              <button
                type="button"
                id="cart-country-uk-btn"
                onClick={() => handleCountryChange("United Kingdom")}
                className={`px-2 py-1 text-[11px] font-bold rounded-lg border transition-all ${
                  shippingForm.shipping_country === "United Kingdom"
                    ? "bg-amber-500 text-slate-950 border-amber-600 shadow-xs"
                    : "bg-white text-slate-700 border-slate-300 hover:bg-slate-50"
                }`}
              >
                🇬🇧 UK
              </button>
            </div>
          </div>
        )}

        {/* ========================================================= */}
        {/* BODY CONTENT: STEP BY STEP                                */}
        {/* ========================================================= */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-5 space-y-5 bg-slate-50">
          {/* STEP 1: CART VIEW */}
          {step === "cart" && (
            <>
              {items.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-center p-6 space-y-4">
                  <div className="w-20 h-20 rounded-3xl bg-slate-200/80 flex items-center justify-center text-slate-400">
                    <ShoppingCart className="w-10 h-10" />
                  </div>
                  <div className="space-y-1 max-w-xs">
                    <h4 className="text-base font-black text-slate-900">Your basket is empty</h4>
                    <p className="text-xs text-slate-500">
                      You haven&apos;t added any verified spare parts to your shopping cart yet.
                    </p>
                  </div>
                  <button
                    type="button"
                    onClick={handleBrowseParts}
                    className="mt-2 px-5 py-2.5 bg-slate-900 hover:bg-slate-800 text-white text-xs font-bold rounded-xl transition-all shadow-md flex items-center gap-2"
                  >
                    <Wrench className="w-4 h-4 text-amber-400" />
                    <span>Browse Spare Parts Marketplace</span>
                  </button>
                </div>
              ) : (
                <>
                  {/* Vehicle Advisory if vehicle is in cart */}
                  {hasVehicles && (
                    <div className="p-3 bg-amber-50 rounded-xl border border-amber-200 text-amber-950 text-xs flex items-start gap-2">
                      <Car className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
                      <div className="space-y-0.5">
                        <span className="font-bold text-amber-900 block">Vehicles are enquiry-based</span>
                        <p className="text-[11px] text-amber-800">
                          Automated checkout is supported strictly for spare parts. Motor vehicles require legal documentation, physical inspection, and title transfer. Please contact the seller via the Contact Seller button on the listing.
                        </p>
                      </div>
                    </div>
                  )}

                  {/* Grouped by Seller / Dealership */}
                  {groupedBySeller.map((group) => (
                    <div
                      key={group.sellerKey}
                      className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-xs space-y-3 p-4"
                    >
                      {/* Seller Header */}
                      <div className="flex items-center justify-between pb-2 border-b border-slate-100">
                        <div className="flex items-center gap-2 min-w-0">
                          <div className="w-6 h-6 rounded-lg bg-amber-50 border border-amber-200 flex items-center justify-center text-amber-600 shrink-0">
                            <Store className="w-3.5 h-3.5" />
                          </div>
                          <div className="min-w-0">
                            <span className="text-xs font-black text-slate-900 truncate block">
                              {group.sellerName}
                            </span>
                            {group.organisationName && (
                              <span className="text-[10px] text-slate-500 block truncate">
                                Dealership: {group.organisationName}
                              </span>
                            )}
                          </div>
                        </div>
                        <div className="text-right shrink-0">
                          <span className="text-[10px] uppercase font-bold text-slate-400 block">
                            Subtotal
                          </span>
                          <span className="text-xs font-black text-slate-900 font-mono">
                            {currency} {group.subtotal.toFixed(2)}
                          </span>
                        </div>
                      </div>

                      {/* Items for this seller */}
                      <div className="space-y-3">
                        {group.items.map((item) => (
                          <CartItemRow
                            key={item.listing_id}
                            item={item}
                            onUpdateQuantity={(qty) => updateQuantity(item.listing_id, qty)}
                            onRemove={() => removeItem(item.listing_id)}
                          />
                        ))}
                      </div>
                    </div>
                  ))}
                </>
              )}
            </>
          )}

          {/* STEP 2: SHIPPING FORM */}
          {step === "shipping" && (
            <div className="space-y-5">
              <div className="bg-white rounded-2xl border border-slate-200 p-4 sm:p-5 shadow-xs space-y-4">
                <div className="flex items-center gap-2 pb-2 border-b border-slate-100">
                  <div className="w-7 h-7 rounded-lg bg-amber-100 text-amber-800 flex items-center justify-center font-bold">
                    <Truck className="w-4 h-4" />
                  </div>
                  <div>
                    <h4 className="text-xs font-black text-slate-900 uppercase tracking-wide">
                      Buyer & Delivery Details
                    </h4>
                    <p className="text-[10px] text-slate-500">
                      Statutory GST and shipping dispatch depend on your destination state
                    </p>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5 text-xs">
                  {/* Recipient Full Name */}
                  <div className="sm:col-span-2 space-y-1">
                    <label className="font-bold text-slate-700 flex items-center gap-1">
                      <UserIcon className="w-3 h-3 text-slate-400" />
                      <span>Full Name / Company Name *</span>
                    </label>
                    <input
                      type="text"
                      id="shipping-name-input"
                      value={shippingForm.shipping_name}
                      onChange={(e) =>
                        setShippingForm((p) => ({ ...p, shipping_name: e.target.value }))
                      }
                      placeholder="e.g. Rahul Sharma"
                      className={`w-full px-3 py-2 bg-slate-50 rounded-xl border ${
                        fieldErrors.shipping_name ? "border-rose-400 bg-rose-50/30" : "border-slate-200"
                      } focus:outline-hidden focus:border-amber-500 text-slate-900`}
                    />
                    {fieldErrors.shipping_name && (
                      <p className="text-[10px] text-rose-600 font-medium">{fieldErrors.shipping_name}</p>
                    )}
                  </div>

                  {/* Phone Number */}
                  <div className="sm:col-span-2 space-y-1">
                    <label className="font-bold text-slate-700 flex items-center gap-1">
                      <Phone className="w-3 h-3 text-slate-400" />
                      <span>Contact Phone Number *</span>
                    </label>
                    <input
                      type="tel"
