  // Handle external navigation (from Global Search) to a specific vehicle
  useEffect(() => {
    if (!initialVehicleId) return;
    api.marketplace
      .getVehicle(initialVehicleId)
      .then((v) => {
        setActiveTab("vehicles");
        setSelectedVehicle(v);
        setSelectedVehicleImageIdx(0);
      })
      .catch(console.error);
  }, [initialVehicleId]);

  // Reviews and Seller Reputation Loaders (Task 4)
  const loadPartReviewsAndReputation = useCallback(async (partId: string, sellerId?: string | number) => {
    setPartReviewsLoading(true);
    try {
      const [reviewsRes, ratingSummaryRes] = await Promise.all([
        api.marketplace.getPartReviews(partId),
        api.marketplace.getPartRatingSummary(partId),
      ]);
      setPartReviews(reviewsRes?.results || []);
      setPartRatingSummary(ratingSummaryRes || null);
    } catch (err) {
      console.error("Failed to load part reviews", err);
      setPartReviews([]);
      setPartRatingSummary(null);
    } finally {
      setPartReviewsLoading(false);
    }

    if (sellerId) {
      setSellerReputationLoading(true);
      try {
        const rep = await api.marketplace.getSellerReputation(String(sellerId));
        setSellerReputation(rep);
      } catch (err) {
        console.error("Failed to load seller reputation", err);
        setSellerReputation(null);
      } finally {
        setSellerReputationLoading(false);
      }
    } else {
      setSellerReputation(null);
    }
  }, []);

  // Handle external navigation (from Global Search) to a specific spare part
  useEffect(() => {
    if (!initialPartId) return;
    api.marketplace
      .getPart(initialPartId)
      .then((p) => {
        setActiveTab("parts");
        setSelectedPart(p);
        setSelectedPartImageIdx(0);
        setPartReviewRatingFilter(null);
        loadPartReviewsAndReputation(p.id, p.seller_id || p.seller);
      })
      .catch(console.error);
  }, [initialPartId]);

  const handleOpenEnquiryModal = (vehicle: MarketplaceVehicleListing) => {
    setEnquiryVehicle(vehicle);
    setEnquiryMessage(
      "Hello, I am interested in your listed vehicle. Could you please share more details about its condition, availability and final price?"
    );
    setEnquiryBuyerPhone(user?.phone_number || "");
    setEnquirySuccess(null);
    setEnquiryError(null);
  };

  const handleSendEnquiry = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!enquiryVehicle) return;
    if (!user) {
      setEnquiryError("Please log in to your DriverXtra account to send an enquiry to the seller.");
      return;
    }
    if (enquiryMessage.trim().length < 10) {
      setEnquiryError("Enquiry message must be at least 10 characters long.");
      return;
    }

    setEnquirySubmitting(true);
    setEnquiryError(null);
    try {
      const result = await api.marketplace.enquireVehicle(enquiryVehicle.id, {
        message: enquiryMessage.trim(),
        buyer_phone: enquiryBuyerPhone.trim(),
      });
      setEnquirySuccess(
        `Your enquiry has been sent directly to ${
          enquiryVehicle.seller_info?.name || enquiryVehicle.seller_name || "the seller"
        }! Reference: #${result.id.slice(0, 8)}`
      );
        } catch (err: unknown) {
      const error = err as {
        details?: { detail?: unknown };
        message?: string;
      };

      const msg =
        error.details?.detail ??
        error.message ??
        "Failed to submit enquiry. Please try again.";

      setEnquiryError(
        typeof msg === "string" ? msg : JSON.stringify(msg)
      );
    } finally {
      setEnquirySubmitting(false);
    }
  };

  const handleAddToCart = (partListing: MarketplacePartListing, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (partListing.stock_quantity <= 0 || partListing.availability === "OUT_OF_STOCK") {
      return;
    }
    const result = addItem(
      {
        listing_id: partListing.id,
        listing_type: "part",
        title: partListing.name,
        brand: partListing.brand,
        mpn: partListing.mpn,
        image_url: partListing.primary_image_url || null,
        condition: partListing.condition,
        price: Number(partListing.price),
        currency: partListing.currency || "INR",
        gst_rate:
          partListing.gst_rate !== undefined && partListing.gst_rate !== null
            ? Number(partListing.gst_rate)
            : undefined,
        stock_quantity: partListing.stock_quantity,
        seller_id: partListing.seller || "seller",
        seller_name: partListing.seller_name || "Verified Seller",
        organisation_name: partListing.organisation_name || null,
      },
      1
    );

    setCartFeedback({ id: partListing.id, message: result.message });
    setTimeout(() => setCartFeedback(null), 3000);
  };

  const handleAddOfferToCart = (offer: CataloguePartOffer, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (offer.stock_quantity <= 0 || offer.availability === "OUT_OF_STOCK") {
      return;
    }
    const result = addItem(
      {
        listing_id: offer.id,
        listing_type: "part",
        title: selectedPart?.name || "Spare Part",
        brand: selectedPart?.brand || "Verified Brand",
        mpn: selectedPart?.mpn || "",
        image_url: offer.primary_image_url || selectedPart?.primary_image_url || null,
        condition: offer.condition,
        price: Number(offer.price),
        currency: offer.currency || "INR",
        gst_rate:
          offer.gst_rate !== undefined && offer.gst_rate !== null
            ? Number(offer.gst_rate)
            : undefined,
        stock_quantity: offer.stock_quantity,
        seller_id: offer.seller_name || "seller",
        seller_name: offer.seller_name || "Verified Seller",
        organisation_name: offer.organisation_name || null,
      },
      1
    );

    setCartFeedback({ id: offer.id, message: result.message });
    setTimeout(() => setCartFeedback(null), 3000);
  };

  // Update models when make changes
  useEffect(() => {
    if (!selectedMake) return;
    let ignore = false;
    api.catalogue.getModels(selectedMake).then((res) => {
      if (!ignore) setModels(res);
    }).catch(console.error);
    return () => {
      ignore = true;
    };
  }, [selectedMake]);

  // Fetch approved vehicles
  const fetchVehicles = useCallback(async () => {
    setVehiclesLoading(true);
    try {
      const params: Record<string, string> = {};
      if (vehicleSearch) params.search = vehicleSearch;
      if (selectedMake) params.make_id = selectedMake;
      if (selectedModel) params.model_id = selectedModel;
      if (fuelType) params.fuel_type = fuelType;
      if (transmission) params.transmission = transmission;
      if (maxVehiclePrice) params.price_max = maxVehiclePrice;

      const data = await api.marketplace.browseVehicles(params);
      setVehicles(data);
    } catch (err) {
      console.error("Failed to load approved vehicles", err);
    } finally {
      setVehiclesLoading(false);
    }
  }, [vehicleSearch, selectedMake, selectedModel, fuelType, transmission, maxVehiclePrice]);

  // Load buyer garage vehicles when logged in (Phase 3 Part C)
  useEffect(() => {
    if (!user) return;
    let ignore = false;
    api.garage
