    let ignore = false;

    const loadParts = async () => {
      try {
        const params: Record<string, string | number | boolean> = {
          page: currentPage,
          page_size: pageSize,
          sort: sortOption,
          include_facets: true,
        };
        if (debouncedSearch) params.search = debouncedSearch;
        if (partBrand) params.brand = partBrand;
        if (partMpn) params.mpn = partMpn;
        if (selectedCategory) params.category_id = selectedCategory;
        if (maxPartPrice) params.price_max = maxPartPrice;
        if (conditionFilter) params.condition = conditionFilter;
        if (inStockOnly) params.in_stock = true;
        if (selectedVehicleId) {
          params.fits_vehicle = selectedVehicleId;
          if (effectiveFitsOnly) {
            params.fits_only = true;
          }
        }

        const res = await api.marketplace.browsePartsPaginated(params);
        if (!ignore) {
          setParts(res.results || []);
          setTotalCount(res.count || 0);
          if (res.facets) {
            setFacets(res.facets);
          }
          setPartsError(null);
        }
      } catch (err: unknown) {
        if (!ignore) {
          console.error("Failed to load approved parts", err);
          const msg =
            err instanceof Error
              ? err.message
              : "Failed to load parts. Please verify your search and filter parameters.";
          setPartsError(msg);
          setParts([]);
          setTotalCount(0);
        }
      } finally {
        if (!ignore) {
          setPartsLoading(false);
        }
      }
    };

    loadParts();
    return () => {
      ignore = true;
    };
  }, [
    activeTab,
    debouncedSearch,
    partBrand,
    partMpn,
    selectedCategory,
    maxPartPrice,
    conditionFilter,
    inStockOnly,
    selectedVehicleId,
    effectiveFitsOnly,
    sortOption,
    currentPage,
    pageSize,
  ]);

  useEffect(() => {
    let ignore = false;
    const loadVehicles = async () => {
      try {
        if (activeTab === "vehicles") {
          const params: Record<string, string> = {};
          if (vehicleSearch) params.search = vehicleSearch;
          if (selectedMake) params.make_id = selectedMake;
          if (selectedModel) params.model_id = selectedModel;
          if (fuelType) params.fuel_type = fuelType;
          if (transmission) params.transmission = transmission;
          if (maxVehiclePrice) params.price_max = maxVehiclePrice;

          const data = await api.marketplace.browseVehicles(params);
          if (!ignore) setVehicles(data);
        }
      } catch (err) {
        if (!ignore) console.error("Failed to load browse vehicles", err);
      }
    };
    loadVehicles();
    return () => {
      ignore = true;
    };
  }, [
    activeTab,
    vehicleSearch,
    selectedMake,
    selectedModel,
    fuelType,
    transmission,
    maxVehiclePrice,
  ]);

  const handleRatingFilterChange = (star: number | null) => {
    setPartReviewRatingFilter(star);
    if (selectedPart) {
      setPartReviewsLoading(true);
      api.marketplace
        .getPartReviews(selectedPart.id, star ? { rating: star } : undefined)
        .then((res) => setPartReviews(res?.results || []))
        .catch((err) => console.error("Error filtering reviews", err))
        .finally(() => setPartReviewsLoading(false));
    }
  };

  const handleVoteHelpful = async (reviewId: string) => {
    if (!user) {
      alert("Please log in to vote on reviews.");
      return;
    }
    setVotingHelpfulId(reviewId);
    try {
      const res = await api.marketplace.voteReviewHelpful(reviewId);
      setPartReviews((prev) =>
        prev.map((r) =>
          r.id === reviewId
            ? { ...r, helpful_count: res.helpful_count, has_voted_helpful: res.has_voted }
            : r
        )
      );
    } catch (err) {
      console.error("Failed to vote helpful", err);
    } finally {
      setVotingHelpfulId(null);
    }
  };

  const handleOpenReportModal = (review: PlatformProductReview) => {
    setReportingReview(review);
    setReportReason("SPAM");
    setReportDetails("");
    setReportSuccess(null);
    setReportError(null);
  };

  const handleSubmitReport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!reportingReview) return;
    if (!user) {
      setReportError("Please log in to report a review.");
      return;
    }
    setReportSubmitting(true);
    setReportError(null);
    try {
      await api.marketplace.reportReview(reportingReview.id, {
        reason: reportReason,
        details: reportDetails,
      });
      setReportSuccess("Thank you. Your report has been submitted to platform administrators.");
      setTimeout(() => {
        setReportingReview(null);
        setReportSuccess(null);
      }, 1800);
    } catch (err: unknown) {
      const e = err as Error;
      setReportError(e?.message || "Failed to submit report. Please try again.");
    } finally {
      setReportSubmitting(false);
    }
  };

  // Open part inspector & load other offers for linked catalogue part (Phase 3 Part B)
  const handleSelectPart = (part: MarketplacePartListing) => {
    setSelectedPart(part);
    setSelectedPartImageIdx(0);
    setPartReviewRatingFilter(null);
    loadPartReviewsAndReputation(part.id, part.seller_id || part.seller);
    if (selectedVehicleId) {
      api.marketplace
        .getPart(part.id, { fits_vehicle: selectedVehicleId })
        .then((detailed) => {
          setSelectedPart(detailed);
        })
        .catch(console.error);
