    if (part.catalogue_part) {
      setOffersLoading(true);
      api.marketplace
        .getCataloguePartOffers(part.catalogue_part)
        .then(setCatalogueOffers)
        .catch((err) => {
          console.error("Failed to load catalogue part offers", err);
          setCatalogueOffers([]);
