                value={maxVehiclePrice}
                onChange={(e) => setMaxVehiclePrice(e.target.value)}
                className="w-full md:w-32 px-3 py-2 text-xs bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:border-amber-500"
