"use client";

import React, { useState, useEffect, useCallback } from "react";
import {
  api,
  GarageVehicle,
  AddGarageVehiclePayload,
  VehicleMake,
  VehicleModel,
  VehicleVariant,
  VehicleServiceRecord,
  CreateServiceRecordPayload,
  ApiError,
} from "@/lib/api/client";
import {
  Car,
  Plus,
  Star,
  Trash2,
  Edit2,
  Gauge,
  AlertCircle,
  CheckCircle2,
  RefreshCw,
  X,
  Fuel,
  ShieldCheck,
  Wrench,
  Calendar,
  Building2,
  Eye,
  FileText,
  DollarSign,
  User,
  History,
  Check,
} from "lucide-react";

interface Phase2GarageViewProps {
  initialVehicleId?: string;
}

export default function Phase2GarageView({ initialVehicleId }: Phase2GarageViewProps = {}) {
  const [vehicles, setVehicles] = useState<GarageVehicle[]>([]);
  const [selectedVehicle, setSelectedVehicle] = useState<GarageVehicle | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);

  // Modal states
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [vehicleToDelete, setVehicleToDelete] = useState<GarageVehicle | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Add vehicle mode: "catalogue" or "manual"
  const [addMode, setAddMode] = useState<"catalogue" | "manual">("catalogue");

  // Catalogue cascading select states
  const [makes, setMakes] = useState<VehicleMake[]>([]);
  const [models, setModels] = useState<VehicleModel[]>([]);
  const [variants, setVariants] = useState<VehicleVariant[]>([]);
  const [selectedMakeId, setSelectedMakeId] = useState("");
  const [selectedModelId, setSelectedModelId] = useState("");
  const [selectedVariantId, setSelectedVariantId] = useState("");

  // Service History States
  const [serviceRecords, setServiceRecords] = useState<VehicleServiceRecord[]>([]);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const [isAddServiceModalOpen, setIsAddServiceModalOpen] = useState(false);
  const [serviceToEdit, setServiceToEdit] = useState<VehicleServiceRecord | null>(null);
  const [serviceToDelete, setServiceToDelete] = useState<VehicleServiceRecord | null>(null);
  const [serviceDetailToView, setServiceDetailToView] = useState<VehicleServiceRecord | null>(null);

  // Service Form fields
  const [serviceFormTitle, setServiceFormTitle] = useState("");
  const [serviceFormDate, setServiceFormDate] = useState(new Date().toISOString().split("T")[0]);
  const [serviceFormType, setServiceFormType] = useState("SERVICE");
  const [serviceFormCentre, setServiceFormCentre] = useState("");
  const [serviceFormOdometer, setServiceFormOdometer] = useState<number | "">("");
  const [serviceFormCost, setServiceFormCost] = useState("");
  const [serviceFormCurrency, setServiceFormCurrency] = useState("GBP");
  const [serviceFormDesc, setServiceFormDesc] = useState("");
  const [serviceFormNotes, setServiceFormNotes] = useState("");
  const [serviceFormError, setServiceFormError] = useState<string | null>(null);

  // Common Add Form fields
  const [formPlate, setFormPlate] = useState("");
  const [formVin, setFormVin] = useState("");
  const [formNickname, setFormNickname] = useState("");
  const [formOdometer, setFormOdometer] = useState<number | "">("");
  const [formColor, setFormColor] = useState("");

  // Manual Add Form fields
  const [formManualMake, setFormManualMake] = useState("");
  const [formManualModel, setFormManualModel] = useState("");
  const [formManualYear, setFormManualYear] = useState<number | "">(new Date().getFullYear());
  const [formManualTrim, setFormManualTrim] = useState("");
  const [formManualFuel, setFormManualFuel] = useState("PETROL");
  const [formManualTransmission, setFormManualTransmission] = useState("MANUAL");

  // Edit Form fields
  const [editPlate, setEditPlate] = useState("");
  const [editNickname, setEditNickname] = useState("");
  const [editOdometer, setEditOdometer] = useState<number | "">("");
  const [editColor, setEditColor] = useState("");

  const showSuccess = (msg: string) => {
    setActionSuccess(msg);
    setTimeout(() => setActionSuccess(null), 4000);
  };

  const loadVehicles = useCallback(async () => {
    try {
      setIsLoading(true);
      setErrorMsg(null);
      const data = await api.garage.listVehicles();
      setVehicles(data);
      if (data.length > 0) {
        setSelectedVehicle((prev) => {
          if (!prev) return data[0];
          const found = data.find((v) => v.id === prev.id);
          return found || data[0];
        });
      } else {
        setSelectedVehicle(null);
      }
    } catch (err: unknown) {
      setErrorMsg(err instanceof ApiError ? err.message : "Failed to load garage vehicles. Please refresh or try again.");
    } finally {
      setIsLoading(false);
    }
  }, []);

  const loadServiceHistory = useCallback(async (vehicleId: string) => {
    try {
      setIsLoadingHistory(true);
      const records = await api.garage.listServiceRecords(vehicleId);
      setServiceRecords(records);
    } catch (err: unknown) {
      console.error("Failed to load vehicle service history:", err);
    } finally {
      setIsLoadingHistory(false);
    }
  }, []);

  useEffect(() => {
    if (selectedVehicle?.id) {
      loadServiceHistory(selectedVehicle.id);
    } else {
      setServiceRecords([]);
    }
  }, [selectedVehicle?.id, loadServiceHistory]);

  const handleOpenAddServiceModal = () => {
    setServiceToEdit(null);
    setServiceFormTitle("");
    setServiceFormDate(new Date().toISOString().split("T")[0]);
    setServiceFormType("SERVICE");
    setServiceFormCentre("");
    setServiceFormOdometer(selectedVehicle?.current_odometer ?? "");
    setServiceFormCost("");
    setServiceFormCurrency("GBP");
    setServiceFormDesc("");
    setServiceFormNotes("");
    setServiceFormError(null);
    setIsAddServiceModalOpen(true);
  };

  const handleOpenEditServiceModal = (rec: VehicleServiceRecord) => {
    setServiceToEdit(rec);
    setServiceFormTitle(rec.service_title);
    setServiceFormDate(rec.service_date);
    setServiceFormType(rec.service_type || "SERVICE");
    setServiceFormCentre(rec.service_centre_name || "");
    setServiceFormOdometer(rec.odometer_reading ?? "");
    setServiceFormCost(rec.total_cost ?? "");
    setServiceFormCurrency(rec.currency || "GBP");
    setServiceFormDesc(rec.description || "");
    setServiceFormNotes(rec.notes || "");
    setServiceFormError(null);
    setIsAddServiceModalOpen(true);
  };

  const handleSaveServiceRecord = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedVehicle) return;

    if (!serviceFormTitle.trim()) {
      setServiceFormError("Service title is required.");
      return;
    }
    if (!serviceFormDate) {
      setServiceFormError("Service date is required.");
      return;
    }
    const todayStr = new Date().toISOString().split("T")[0];
    if (serviceFormDate > todayStr) {
      setServiceFormError("Service date cannot be in the future.");
      return;
    }

    setIsSubmitting(true);
    setServiceFormError(null);

    try {
      const payload: CreateServiceRecordPayload = {
        service_title: serviceFormTitle.trim(),
        service_date: serviceFormDate,
        service_type: serviceFormType,
        service_centre_name: serviceFormCentre.trim() || undefined,
        odometer_reading: serviceFormOdometer === "" ? null : Number(serviceFormOdometer),
        odometer_unit: selectedVehicle.odometer_unit || "mi",
        total_cost: serviceFormCost === "" ? null : serviceFormCost,
        currency: serviceFormCurrency || "GBP",
        description: serviceFormDesc.trim() || undefined,
        notes: serviceFormNotes.trim() || undefined,
      };

      if (serviceToEdit) {
        await api.garage.updateServiceRecord(serviceToEdit.id, payload);
        showSuccess(`Service record "${payload.service_title}" updated successfully.`);
      } else {
        await api.garage.createServiceRecord(selectedVehicle.id, payload);
        showSuccess(`Historical service record logged in vehicle passport.`);
      }

      setIsAddServiceModalOpen(false);
      await loadServiceHistory(selectedVehicle.id);
    } catch (err: unknown) {
      setServiceFormError(err instanceof ApiError ? err.message : "Failed to save service record.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteServiceRecord = async () => {
    if (!serviceToDelete || !selectedVehicle) return;
    setIsSubmitting(true);
    try {
      await api.garage.deleteServiceRecord(serviceToDelete.id);
      showSuccess(`Service record "${serviceToDelete.service_title}" deleted.`);
      setServiceToDelete(null);
      await loadServiceHistory(selectedVehicle.id);
    } catch (err: unknown) {
      setErrorMsg(err instanceof ApiError ? err.message : "Failed to delete service record.");
    } finally {
      setIsSubmitting(false);
    }
  };

  useEffect(() => {
    let ignore = false;
    api.garage.listVehicles()
      .then((data) => {
        if (!ignore) {
          setVehicles(data);
          if (data.length > 0) setSelectedVehicle(data[0]);
          setIsLoading(false);
        }
      })
      .catch((err: unknown) => {
        if (!ignore) {
          setErrorMsg(err instanceof ApiError ? err.message : "Failed to load garage vehicles. Please refresh or try again.");
          setIsLoading(false);
        }
      });

    return () => {
      ignore = true;
    };
  }, []);

  // Handle external navigation (from Global Search) to a specific garage vehicle
  useEffect(() => {
    if (!initialVehicleId || vehicles.length === 0) return;
    const match = vehicles.find((v) => v.id === initialVehicleId);
    if (match) {
      const timer = setTimeout(() => {
        setSelectedVehicle(match);
      }, 0);
      return () => clearTimeout(timer);
    }
  }, [initialVehicleId, vehicles]);

  // Load makes when add modal opens
  useEffect(() => {
    if (!isAddModalOpen || makes.length > 0) return;
    let ignore = false;
    api.catalogue.getMakes().then((res) => {
      if (!ignore) setMakes(res);
    }).catch(() => {});
    return () => {
      ignore = true;
    };
  }, [isAddModalOpen, makes.length]);

  // Cascading models
  useEffect(() => {
    if (!selectedMakeId) return;
    let ignore = false;
    api.catalogue.getModels(selectedMakeId).then((res) => {
      if (!ignore) setModels(res);
    }).catch(() => {});
    return () => {
      ignore = true;
    };
  }, [selectedMakeId]);

  // Cascading variants
  useEffect(() => {
    if (!selectedModelId) return;
    let ignore = false;
    api.catalogue.getVariants(selectedModelId).then((res) => {
      if (!ignore) setVariants(res);
    }).catch(() => {});
    return () => {
      ignore = true;
    };
  }, [selectedModelId]);

  const handleSetPrimary = async (vehicleId: string) => {
    try {
      setErrorMsg(null);
      await api.garage.setPrimary(vehicleId);
      showSuccess("Primary vehicle updated successfully.");
      await loadVehicles();
    } catch (err: unknown) {
      setErrorMsg(err instanceof ApiError ? err.message : "Failed to set primary vehicle.");
    }
  };

  const handleArchiveVehicle = async () => {
    if (!vehicleToDelete) return;
    try {
      setIsSubmitting(true);
      setErrorMsg(null);
      await api.garage.archiveVehicle(vehicleToDelete.id);
      showSuccess(`Vehicle ${vehicleToDelete.year} ${vehicleToDelete.make} ${vehicleToDelete.model} archived.`);
      setVehicleToDelete(null);
      await loadVehicles();
    } catch (err: unknown) {
      setErrorMsg(err instanceof ApiError ? err.message : "Failed to archive vehicle.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleAddVehicle = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setErrorMsg(null);

    try {
      const payload: AddGarageVehiclePayload = {
        registration_plate: formPlate.trim().toUpperCase() || undefined,
        vin: formVin.trim().toUpperCase() || undefined,
        nickname: formNickname.trim() || undefined,
        color: formColor.trim() || undefined,
        current_odometer: formOdometer === "" ? undefined : Number(formOdometer),
      };

      if (addMode === "catalogue") {
        if (!selectedVariantId) {
          setErrorMsg("Please select a vehicle variant from the catalogue.");
          setIsSubmitting(false);
          return;
        }
        payload.vehicle_variant = selectedVariantId;
      } else {
        if (!formManualMake.trim() || !formManualModel.trim() || !formManualYear) {
          setErrorMsg("Make, model, and year are required for manual vehicle entry.");
          setIsSubmitting(false);
          return;
        }
        payload.make = formManualMake.trim();
        payload.model = formManualModel.trim();
        payload.year = Number(formManualYear);
        payload.trim = formManualTrim.trim() || undefined;
        payload.fuel_type = formManualFuel;
        payload.transmission = formManualTransmission;
      }

      const created = await api.garage.addVehicle(payload);
      showSuccess(`Vehicle ${created.year} ${created.make} ${created.model} added to your garage.`);
      setIsAddModalOpen(false);
      resetAddForm();
      await loadVehicles();
      setSelectedVehicle(created);
    } catch (err: unknown) {
      setErrorMsg(err instanceof ApiError ? err.message : "Failed to add vehicle.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleEditVehicle = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedVehicle) return;
    setIsSubmitting(true);
    setErrorMsg(null);

    try {
      const updated = await api.garage.updateVehicle(selectedVehicle.id, {
        registration_plate: editPlate.trim().toUpperCase() || undefined,
        nickname: editNickname.trim() || undefined,
        color: editColor.trim() || undefined,
        current_odometer: editOdometer === "" ? undefined : Number(editOdometer),
      });
      showSuccess(`Vehicle ${updated.make} ${updated.model} details updated.`);
      setIsEditModalOpen(false);
      await loadVehicles();
      setSelectedVehicle(updated);
    } catch (err: unknown) {
      setErrorMsg(err instanceof ApiError ? err.message : "Failed to update vehicle.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const openEditModal = (vehicle: GarageVehicle) => {
    setSelectedVehicle(vehicle);
    setEditPlate(vehicle.registration_plate || "");
    setEditNickname(vehicle.nickname || "");
    setEditOdometer(vehicle.current_odometer ?? "");
    setEditColor(vehicle.color || "");
    setIsEditModalOpen(true);
  };

  const resetAddForm = () => {
    setSelectedMakeId("");
    setSelectedModelId("");
    setSelectedVariantId("");
    setFormPlate("");
    setFormVin("");
    setFormNickname("");
    setFormOdometer("");
    setFormColor("");
    setFormManualMake("");
    setFormManualModel("");
    setFormManualYear(new Date().getFullYear());
    setFormManualTrim("");
