                            {p.fitment_summary.conditional > 0 && (
                              <span className="px-2 py-0.5 rounded-full bg-amber-50 text-amber-800 text-[10px] font-bold border border-amber-200">
                                {p.fitment_summary.conditional} Conditional
                              </span>
