                            {shp.items.map((si) => (
                              <span
                                key={si.id}
                                className="px-2 py-1 rounded bg-slate-100 text-slate-800 text-[11px] font-medium"
                              >
                                {si.quantity}x {si.listing_title} ({si.listing_brand})
                              </span>
