                            ? "bg-amber-50/50 border-amber-200"
                            : co.status === "APPROVED"
                            ? "bg-emerald-50/40 border-emerald-200"
                            : co.status === "REJECTED"
                            ? "bg-rose-50/40 border-rose-200"
                            : "bg-slate-50 border-slate-200"
                        }`}
                      >
                        <div className="flex items-start justify-between gap-2">
