                            </span>
                            <span className="text-[10px] text-slate-400 block font-mono">
                              Revised: £{parseFloat(co.revised_authorized_total).toFixed(2)}
                            </span>
                          </div>
                        </div>

                        {/* Line Items Table */}
                        <div className="overflow-x-auto bg-white rounded-lg border border-slate-200">
