          method: "POST",
          requiresAuth: true,
          body: JSON.stringify({ reason }),
        });
      },
    },

    manageTechnicians: {
      async list(): Promise<WorkshopTechnicianMember[]> {
        const res = await apiRequest<{ results: WorkshopTechnicianMember[] } | WorkshopTechnicianMember[]>("/workshops/manage/technicians/", {
          method: "GET",
